 35| export class ScaleService {
 36|   constructor(
 37|     private readonly scales: ScaleRepository,
 38|     private readonly readings: WeightReadingRepository,
 39|     private readonly hives: HiveRepository,
 40|     private readonly sms: SmsGateway,
 41|     private readonly inspections: InspectionRepository,
 42|     private readonly holdMs: number = INSPECTION_AFTER_MS,
 43|   ) {}
