 45|   private readonly pending = new Set<PendingAlert>();
 46| 
 47|   linkScale(
 48|     memberId: string | undefined,
 49|     hiveId: string,
 50|     input: { serialNumber?: unknown; phoneNumber?: unknown },
 51|   ): Scale {
 52|     if (!memberId || memberId.trim() === "") {
 53|       throw new DomainError("unauthorized", "Member id header is required");
 54|     }
 55|     const ownerId = memberId.trim();
 56|     const hive = this.hives.findById(hiveId);
 57|     if (!hive) throw new DomainError("not_found", "Hive not found");
 58|     if (hive.ownerId !== ownerId) {
 59|       throw new DomainError("forbidden", "Only the hive owner can link a scale");
 60|     }
 61|     const serialNumber = requireString(input.serialNumber, "serialNumber");
 62|     const phoneNumber = requireString(input.phoneNumber, "phoneNumber");
 63|     const existing = this.scales.findBySerial(serialNumber);
 64|     if (existing && existing.ownerId !== ownerId) {
 65|       throw new DomainError("forbidden", "Scale is linked to another member");
 66|     }
 67|     return this.scales.save({ serialNumber, hiveId, ownerId, phoneNumber });
 68|   }
