 70|   async recordReading(input: {
 71|     serialNumber?: unknown;
 72|     kilograms?: unknown;
 73|     time?: unknown;
 74|   }): Promise<ReadingResult> {
 75|     const serialNumber = requireString(input.serialNumber, "serialNumber");
 76|     const kilograms = input.kilograms;
 77|     if (typeof kilograms !== "number" || !Number.isFinite(kilograms)) {
 78|       throw new DomainError("validation", "kilograms must be a number");
 79|     }
 80|     const timestamp =
 81|       typeof input.time === "string" || typeof input.time === "number"
 82|         ? new Date(input.time).getTime()
 83|         : NaN;
 84|     if (Number.isNaN(timestamp)) {
 85|       throw new DomainError("validation", "time must be a valid timestamp");
 86|     }
 87|     const scale = this.scales.findBySerial(serialNumber);
 88|     if (!scale) throw new DomainError("not_found", "Scale not linked to a hive");
 89| 
 90|     const recent = this.readings.findBySerialBetween(
 91|       serialNumber,
 92|       timestamp - SWARM_WINDOW_MS,
 93|       timestamp,
 94|     );
 95|     this.readings.add({ serialNumber, kilograms, timestamp });
 96| 
 97|     const peak = recent.reduce((max, r) => Math.max(max, r.kilograms), -Infinity);
 98|     const drop = peak - kilograms;
 99|     const swarmSuspected = recent.length > 0 && drop > SWARM_DROP_KG;
100|     if (swarmSuspected && !this.hasNearbyInspection(scale.hiveId, timestamp)) {
101|       const hive = this.hives.findById(scale.hiveId);
102|       const name = hive ? hive.name : scale.hiveId;
103|       this.holdAlert(
104|         scale.hiveId,
105|         timestamp,
106|         scale.phoneNumber,
107|         `Possible swarm: hive "${name}" lost ${drop.toFixed(1)} kg within one hour.`,
108|       );
109|     }
110|     return { accepted: true, swarmSuspected };
111|   }
