113|   // Called when an inspection is recorded: cancels held SMS alerts it explains.
114|   cancelAlertsForInspection(hiveId: string, inspectionTime: number): void {
115|     for (const alert of [...this.pending]) {
116|       if (alert.hiveId === hiveId && this.explains(inspectionTime, alert.dropTime)) {
117|         clearTimeout(alert.timer);
118|         this.pending.delete(alert);
119|       }
120|     }
121|   }
122| 
123|   private explains(inspectionTime: number, dropTime: number): boolean {
124|     return (
125|       inspectionTime >= dropTime - INSPECTION_BEFORE_MS &&
126|       inspectionTime <= dropTime + INSPECTION_AFTER_MS
127|     );
128|   }
129| 
130|   private hasNearbyInspection(hiveId: string, dropTime: number): boolean {
131|     return this.inspections
132|       .findByHive(hiveId)
133|       .some((i) => this.explains(Date.parse(i.date), dropTime));
134|   }
