136|   private holdAlert(hiveId: string, dropTime: number, phone: string, message: string): void {
137|     const alert: PendingAlert = {
138|       hiveId,
139|       dropTime,
140|       timer: setTimeout(() => {
141|         this.pending.delete(alert);
142|         this.sms.send(phone, message).catch((err) => {
143|           console.error("Failed to send swarm SMS", err);
144|         });
145|       }, this.holdMs),
146|     };
147|     alert.timer.unref?.();
148|     this.pending.add(alert);
149|   }
150| }
